import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as r,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Google Flow","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/gemini/flow.md","filePath":"products/ai-coding/gemini/flow.md","lastUpdated":1787044708000}'),n={name:"products/ai-coding/gemini/flow.md"};function i(l,e,s,d,g,h){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="google-flow" tabindex="-1">Google Flow <a class="header-anchor" href="#google-flow" aria-label="Permalink to &quot;Google Flow&quot;">​</a></h1><blockquote><p>Google&#39;s AI creative studio. Frontend engineers use it for <strong>landing-page films, product demos and scene boards</strong>, not for writing code.</p><p>Entry point: <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">labs.google/fx/tools/flow</a>. Help centre: <a href="https://support.google.com/flow" target="_blank" rel="noreferrer">support.google.com/flow</a>.</p></blockquote><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Officially an <strong>AI creative studio</strong>: plan, generate and refine in natural language, on top of Google&#39;s generative models.</p><p>The landing page currently lists three model families:</p><table tabindex="0"><thead><tr><th>Model</th><th>Official one-liner</th></tr></thead><tbody><tr><td><strong>Gemini Omni</strong></td><td>create and edit videos from any input reference — real or generated; world understanding, multimodality, conversational editing</td></tr><tr><td><strong>Nano Banana</strong></td><td>image generation and precise editing; subject consistency, text rendering, reasoning</td></tr><tr><td><strong>Veo 3.1</strong></td><td>video generation; physics, realism, prompt adherence, native audio and expanded controls</td></tr></tbody></table><p>It is off the coding main line. The counterpart in the Claude family is <a href="./../claude/claude-design.html">Claude Design</a>: Design hands off an interface prototype; Flow hands off a piece of film.</p><p><strong>Age and language</strong>: you must be 18 or older. Prompts to Flow are English only; replies are English. <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Official note</a>.</p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want…</th><th>Use</th><th>Do not use Flow</th></tr></thead><tbody><tr><td>A <strong>video</strong> for a landing page, launch film or product demo</td><td><strong>Flow</strong></td><td>Canvas produces a clickable page, not a finished clip</td></tr><tr><td>A <strong>clickable prototype</strong> for a PM within half an hour</td><td><a href="./canvas.html">Canvas</a></td><td>Flow does not emit DOM or interaction</td></tr><tr><td>The chosen direction committed to the repo</td><td><a href="./antigravity.html">Antigravity</a></td><td>Flow does not edit code or open a PR</td></tr><tr><td>Songs / music videos / generative score</td><td><a href="https://www.flowmusic.app/" target="_blank" rel="noreferrer">Flow Music</a> (credits are <strong>separate</strong> from Flow)</td><td>Do not treat Flow video credits as music credits</td></tr></tbody></table><p>A useful combination: try three interaction directions in Canvas → pick one → implement it in the real project with Antigravity; when you need to present the feature, make an 8–10 second clip in Flow.</p><h2 id="what-it-can-do" tabindex="-1">What it can do <a class="header-anchor" href="#what-it-can-do" aria-label="Permalink to &quot;What it can do&quot;">​</a></h2><p>Capabilities listed on the <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">product landing page</a> and the <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Pro benefits article</a>:</p><ul><li><strong>Generation modes</strong>: Text to video, Frames to video, Ingredients to video, Text to image, Image to image</li><li><strong>Refinement</strong>: Video Extension, Video-to-video editing, Scenebuilder</li><li><strong>Cast</strong>: Characters, Avatars</li><li><strong>Agent</strong>: described as a project-level creative partner for exploring and iterating</li><li><strong>Custom Tools</strong>: build tools in natural language (type overlays, resize, storyboard, shaders); share and remix. The free tier can <strong>use</strong> existing Tools; <strong>creating</strong> them starts at Plus</li></ul><p><a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">Create videos</a> and <a href="https://support.google.com/flow/answer/16935718" target="_blank" rel="noreferrer">edit / build scenes</a> are the how-to pages. This page does not repeat the steps.</p><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><p>Figures come from <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Manage your Google Flow credits</a> and the landing page — <strong>not</strong> from third-party blogs.</p><table tabindex="0"><thead><tr><th>Tier</th><th>Flow credits</th></tr></thead><tbody><tr><td>No subscription</td><td><strong>50 per day</strong> (trial; unused daily credits do not roll over)</td></tr><tr><td>AI Plus</td><td><strong>200 per month</strong></td></tr><tr><td>AI Pro</td><td><strong>1,000 per month</strong></td></tr><tr><td>AI Ultra $100 (Ultra 5x in this site)</td><td><strong>10,000 per month</strong></td></tr><tr><td>AI Ultra $200 (Ultra 20x in this site)</td><td><strong>25,000 per month</strong></td></tr></tbody></table><p>Key points:</p><ul><li>Paid tiers refresh on the <strong>billing cycle</strong>. Unused monthly credits <strong>do not roll over</strong>.</li><li>Upgrading to a paid plan forfeits leftover free daily credits immediately; they are replaced by the plan&#39;s monthly allocation.</li><li>Free daily credits can be spent only on <strong>Veo 3.1 Lite / Fast / Quality</strong>.</li><li>After the allocation is exhausted, Plus / Pro / Ultra can buy extra AI credits (except in Japan). The same AI credits also work in <a href="./antigravity.html">Antigravity</a>.</li><li>Cost per generation depends on the model (for example Veo 3.1 Lite is 10 credits for non-Ultra, Quality is 100). Use the table on the credits page; this page does not copy it.</li></ul><p>The full four-tier comparison (storage, model multiplier, Cloud credit) lives <strong>only</strong> in the <a href="./gemini-cheatsheet.html#subscription-tiers">cheatsheet</a>.</p><h2 id="flow-sessions" tabindex="-1">Flow Sessions <a class="header-anchor" href="#flow-sessions" aria-label="Permalink to &quot;Flow Sessions&quot;">​</a></h2><p><strong>Flow Sessions</strong> on the <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">landing page</a> is an artist collaboration programme: a small group of creatives is invited to make a passion project in Flow with Google. <strong>It is not a daily product.</strong> Frontend engineers do not need a separate tutorial for it.</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Some older Labs help pages still say you must subscribe to Pro / Ultra. Trust the landing page and the <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">credits article</a>: no subscription still gets 50 credits a day to try Flow.</li><li>A VPN <strong>will not</strong> unlock unsupported regions. Check <a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">Where you can use Flow</a> first.</li><li>Failed generations are not charged. A returned result <strong>is</strong> charged, even without audio or at a quality you dislike.</li><li>All Veo / Imagen output carries an invisible SynthID. </li></ul><h2 id="official-resources" tabindex="-1">Official resources <a class="header-anchor" href="#official-resources" aria-label="Permalink to &quot;Official resources&quot;">​</a></h2><ul><li><a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">Product entry</a></li><li><a href="https://support.google.com/flow" target="_blank" rel="noreferrer">Flow help centre</a></li><li><a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Credits and per-generation cost</a></li><li><a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">Create videos</a></li><li><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro benefits</a></li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./google-pro.html">Subscriptions and quota</a> — other coding-relevant Pro entitlements</li><li><a href="./canvas.html">Canvas</a> — clickable prototypes</li><li><a href="./gemini-cheatsheet.html#which-tool">Cheatsheet</a> — pick a tool by task</li></ul>',29)])])}const b=t(n,[["render",i]]);export{m as __pageData,b as default};
